consecutive-characters:
class Solution:
    def longestContinuousSubstring(self, s: str) -> int:
        best = 1
        cur = 1
        for i in range(1, len(s)):
            if ord(s[i]) == ord(s[i - 1]) + 1:
                cur += 1
            else:
                cur = 1
            best = max(best, cur)
        return best

design-hashmap:
class MyHashMap:
    def __init__(self):
        self.d = {}
    def put(self, key: int, value: int) -> None:
        self.d[key] = value
    def get(self, key: int) -> int:
        return self.d.get(key, -1)
    def remove(self, key: int) -> None:
        self.d.pop(key, None)

design-hashset:
class MyHashSet:
    def __init__(self):
        self.s = set()
    def add(self, key: int) -> None:
        self.s.add(key)
    def remove(self, key: int) -> None:
        self.s.discard(key)
    def contains(self, key: int) -> bool:
        return key in self.s

difference-between-element-sum-and-digit:
class Solution:
    def differenceBetweenElementSumAndDigitSum(self, nums: List[int]) -> int:
        e = sum(nums)
        d = sum(int(c) for x in nums for c in str(x))
        return abs(e - d)

distribute-elements-into-two-arrays-i:
class Solution:
    def distributeElements(self, nums: List[int]) -> List[List[int]]:
        a1 = [nums[0]]
        a2 = [nums[1]]
        for x in nums[2:]:
            if a1[-1] > a2[-1]:
                a1.append(x)
            else:
                a2.append(x)
        return [a1, a2]

faulty-keyboard:
class Solution:
    def faultyKeyboard(self, s: str) -> str:
        res = []
        for c in s:
            if c == 'i':
                res.reverse()
            else:
                res.append(c)
        return ''.join(res)

find-common-elements-between-two-arrays:
class Solution:
    def findCommonElements(self, nums1: List[int], nums2: List[int]) -> List[int]:
        s1 = set(nums1)
        s2 = set(nums2)
        return [sum(1 for x in nums1 if x in s2), sum(1 for x in nums2 if x in s1)]
